# ============================================================================\n# CASME II Inference - Real-time Micro-Expression Classification\n# ============================================================================\n\nimport torch\nimport torch.nn.functional as F\nimport numpy as np\nfrom pathlib import Path\nfrom typing import List, Dict, Tuple, Optional\nimport logging\n\nfrom config import InferenceConfig, Config\nfrom models import build_model\nfrom preprocessing import OpticalFlowProcessor, FrameSequenceProcessor, AugmentationPipeline\nfrom wellness_score import MicroExpressionResult, WellnessScoreCalculator\n\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n\nclass MicroExpressionPredictor:\n    \"\"\"\n    Inference pipeline for micro-expression classification.\n    \n    Supports:\n    - Single video inference\n    - Batch inference\n    - Real-time frame processing\n    - Confidence thresholding\n    - Smoothing predictions over frames\n    \"\"\"\n    \n    def __init__(\n        self,\n        model_path: str,\n        config: InferenceConfig = None,\n        device: torch.device = None,\n    ):\n        \"\"\"\n        Args:\n            model_path: Path to trained model checkpoint\n            config: Inference configuration\n            device: Device to run inference on (cuda/cpu)\n        \"\"\"\n        self.config = config or InferenceConfig()\n        self.device = device or self.config.DEVICE\n        \n        # Build model\n        logger.info(f\"Loading model from {model_path}\")\n        self.model = build_model(\n            model_type=self.config.MODEL_TYPE,\n            num_classes=self.config.NUM_CLASSES,\n            temporal_length=self.config.TEMPORAL_LENGTH,\n            input_channels=4,  # RGB + Optical Flow\n            pretrained_backbone=False,  # Don't need pretrained for inference\n            device=self.device,\n        )\n        \n        # Load weights\n        checkpoint = torch.load(model_path, map_location=self.device)\n        self.model.load_state_dict(checkpoint['model_state_dict'])\n        self.model.eval()\n        \n        logger.info(\"Model loaded successfully\")\n        \n        # Initialize processors\n        self.frame_processor = FrameSequenceProcessor(frame_size=self.config.FRAME_SIZE)\n        self.flow_processor = OpticalFlowProcessor(method=\"farneback\")\n        \n        # Class names\n        self.class_names = self.config.REVERSE_CLASS_MAPPING\n    \n    @torch.no_grad()\n    def predict_batch(\n        self,\n        batch_frames: torch.Tensor,\n        return_probabilities: bool = True,\n        return_features: bool = False,\n    ) -> Dict:\n        \"\"\"\n        Predict emotions for a batch of frame sequences.\n        \n        Args:\n            batch_frames: Tensor of shape (B, T, C, H, W)\n            return_probabilities: Return softmax probabilities\n            return_features: Return intermediate features\n            \n        Returns:\n            Dictionary with predictions and confidence scores\n        \"\"\"\n        batch_frames = batch_frames.to(self.device)\n        \n        if hasattr(self.model, 'forward') and 'return_features' in self.model.forward.__code__.co_varnames:\n            logits, features = self.model(batch_frames, return_features=True)\n        else:\n            logits = self.model(batch_frames)\n            features = None\n        \n        # Get probabilities\n        probabilities = F.softmax(logits, dim=1)  # (B, num_classes)\n        \n        # Get predictions\n        pred_indices = torch.argmax(probabilities, dim=1)  # (B,)\n        pred_classes = [self.class_names[idx.item()] for idx in pred_indices]\n        confidences = probabilities.max(dim=1).values.cpu().numpy()\n        \n        result = {\n            'pred_classes': pred_classes,\n            'confidences': confidences,\n            'pred_indices': pred_indices.cpu().numpy(),\n        }\n        \n        if return_probabilities:\n            prob_dict = {}\n            for class_idx, class_name in self.class_names.items():\n                prob_dict[class_name] = probabilities[:, class_idx].cpu().numpy()\n            result['probabilities'] = prob_dict\n        \n        if return_features and features is not None:\n            result['features'] = features.cpu().numpy()\n        \n        return result\n    \n    def predict_single(\n        self,\n        frame_paths: List[str],\n        confidence_threshold: float = 0.5,\n    ) -> MicroExpressionResult:\n        \"\"\"\n        Predict emotion for a single video sequence.\n        \n        Args:\n            frame_paths: List of frame file paths\n            confidence_threshold: Minimum confidence to report prediction\n            \n        Returns:\n            MicroExpressionResult with emotion, confidence, and probabilities\n        \"\"\"\n        # Load frames\n        frames = self.frame_processor.load_sequence(frame_paths)\n        \n        # Sample temporal frames\n        frames = self.frame_processor.sample_frames(frames, self.config.TEMPORAL_LENGTH)\n        \n        # Normalize\n        frames = self.frame_processor.normalize_frames(\n            frames,\n            self.config.IMG_MEAN,\n            self.config.IMG_STD\n        )\n        \n        # Compute optical flow\n        flows = []\n        for i in range(len(frames) - 1):\n            flow = self.flow_processor.compute_flow(\n                (frames[i] * 255).astype(np.uint8),\n                (frames[i + 1] * 255).astype(np.uint8)\n            )\n            flow_mag = self.flow_processor.normalize_flow(flow)\n            flows.append(flow_mag)\n        flows.append(flows[-1] if flows else np.zeros((*self.config.FRAME_SIZE, 1)))\n        flows = np.array(flows)\n        \n        # Concatenate RGB + Flow\n        frames = np.concatenate([frames, flows], axis=-1)\n        \n        # Convert to tensor (B=1, T, C, H, W)\n        frames_tensor = torch.from_numpy(frames).permute(2, 0, 1).unsqueeze(0).float()\n        \n        # Predict\n        result = self.predict_batch(frames_tensor, return_probabilities=True)\n        \n        # Extract single prediction\n        emotion_class = result['pred_classes'][0]\n        confidence = result['confidences'][0]\n        \n        # Build probability dict\n        emotion_probs = {}\n        for class_name, class_idx in Config.CLASS_MAPPING.items():\n            emotion_probs[class_name] = result['probabilities'][class_name][0]\n        \n        return MicroExpressionResult(\n            emotion_class=emotion_class,\n            confidence=confidence,\n            emotion_probabilities=emotion_probs,\n            affective_score=confidence  # Use confidence as affective score proxy\n        )\n    \n    def predict_video(\n        self,\n        video_path: str,\n        frame_stride: int = 5,\n        window_size: int = 12,\n        overlap: float = 0.5,\n    ) -> List[Dict]:\n        \"\"\"\n        Process video file frame by frame with sliding window.\n        \n        Args:\n            video_path: Path to video file\n            frame_stride: Read every Nth frame\n            window_size: Number of frames per prediction\n            overlap: Overlap ratio between windows [0, 1]\n            \n        Returns:\n            List of predictions with timestamps\n        \"\"\"\n        import cv2\n        \n        cap = cv2.VideoCapture(video_path)\n        fps = cap.get(cv2.CAP_PROP_FPS)\n        total_frames = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))\n        \n        logger.info(f\"Video: {video_path}, FPS: {fps}, Total frames: {total_frames}\")\n        \n        frame_list = []\n        frame_indices = []\n        predictions = []\n        \n        frame_count = 0\n        while True:\n            ret, frame = cap.read()\n            if not ret:\n                break\n            \n            if frame_count % frame_stride == 0:\n                frame_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)\n                frame_rgb = cv2.resize(frame_rgb, self.config.FRAME_SIZE)\n                frame_list.append(frame_rgb)\n                frame_indices.append(frame_count)\n            \n            frame_count += 1\n        \n        cap.release()\n        \n        # Sliding window predictions\n        stride = int(window_size * (1 - overlap))\n        for start_idx in range(0, len(frame_list) - window_size + 1, stride):\n            window_frames = frame_list[start_idx:start_idx + window_size]\n            window_indices = frame_indices[start_idx:start_idx + window_size]\n            \n            # Prepare tensor\n            window_array = np.array(window_frames, dtype=np.float32) / 255.0\n            window_array = self.frame_processor.normalize_frames(\n                window_array,\n                self.config.IMG_MEAN,\n                self.config.IMG_STD\n            )\n            \n            # Optical flow\n            flows = []\n            for i in range(len(window_array) - 1):\n                flow = self.flow_processor.compute_flow(\n                    (window_array[i] * 255).astype(np.uint8),\n                    (window_array[i + 1] * 255).astype(np.uint8)\n                )\n                flow_mag = self.flow_processor.normalize_flow(flow)\n                flows.append(flow_mag)\n            flows.append(flows[-1] if flows else np.zeros((*self.config.FRAME_SIZE, 1)))\n            \n            window_array = np.concatenate([window_array, np.array(flows)], axis=-1)\n            \n            # Tensor\n            window_tensor = torch.from_numpy(window_array).permute(2, 0, 1).unsqueeze(0).float()\n            \n            # Predict\n            result = self.predict_batch(window_tensor, return_probabilities=True)\n            \n            timestamp = window_indices[-1] / fps\n            predictions.append({\n                'timestamp': timestamp,\n                'frame_index': window_indices[-1],\n                'emotion': result['pred_classes'][0],\n                'confidence': result['confidences'][0],\n                'probabilities': {k: v[0] for k, v in result['probabilities'].items()}\n            })\n        \n        logger.info(f\"Completed {len(predictions)} predictions\")\n        return predictions\n    \n    def predict_directory(\n        self,\n        directory: str,\n        pattern: str = \"*.jpg\",\n    ) -> List[Dict]:\n        \"\"\"\n        Batch predict on all video sequences in a directory.\n        \n        Args:\n            directory: Directory containing frame sequences\n            pattern: File pattern to match\n            \n        Returns:\n            List of predictions for each sequence\n        \"\"\"\n        results = []\n        \n        for frame_dir in sorted(Path(directory).iterdir()):\n            if not frame_dir.is_dir():\n                continue\n            \n            frame_paths = sorted(frame_dir.glob(pattern))\n            if len(frame_paths) < 3:\n                logger.warning(f\"Skipping {frame_dir}: insufficient frames\")\n                continue\n            \n            frame_paths = [str(p) for p in frame_paths]\n            \n            try:\n                prediction = self.predict_single(frame_paths)\n                results.append({\n                    'sequence': frame_dir.name,\n                    'emotion': prediction.emotion_class,\n                    'confidence': prediction.confidence,\n                    'probabilities': prediction.emotion_probabilities\n                })\n            except Exception as e:\n                logger.error(f\"Error processing {frame_dir.name}: {e}\")\n        \n        return results\n\n\nif __name__ == \"__main__\":\n    import sys\n    \n    # Example inference\n    config = InferenceConfig()\n    model_path = config.BEST_MODEL_PATH\n    \n    if not Path(model_path).exists():\n        logger.error(f\"Model not found: {model_path}\")\n        logger.info(\"Train the model first using train.py\")\n        sys.exit(1)\n    \n    # Initialize predictor\n    predictor = MicroExpressionPredictor(model_path, config)\n    \n    # Example: Predict on CASME II test sequence\n    test_dir = r\"c:\\Users\\Zenith Joshua\\CASME Ⅱ\\Cropped\\Cropped\\sub01\\EP02_01f\"\n    test_frames = sorted(list(Path(test_dir).glob(\"*.jpg\")))\n    \n    if test_frames:\n        logger.info(f\"Testing on {len(test_frames)} frames...\")\n        frame_paths = [str(f) for f in test_frames[:12]]  # Use first 12 frames\n        \n        result = predictor.predict_single(frame_paths)\n        \n        logger.info(f\"\\nPrediction: {result.emotion_class}\")\n        logger.info(f\"Confidence: {result.confidence:.3f}\")\n        logger.info(f\"Probabilities: {result.emotion_probabilities}\")\n    else:\n        logger.warning(\"No test frames found\")\n